<section class="p-4"><h1 class="h3">Reports</h1><form class="row g-2 mb-3" method="get"><div class="col-auto"><label class="form-label" for="type">Report</label><select class="form-select" id="type" name="type"><?php foreach ($types as $key => $label): ?><option value="<?= esc($key) ?>" <?= $type === $key ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach ?></select></div><div class="col-auto"><label class="form-label" for="from">From</label><input class="form-control" type="date" id="from" name="from" value="<?= esc($from ?? '') ?>"></div><div class="col-auto"><label class="form-label" for="to">To</label><input class="form-control" type="date" id="to" name="to" value="<?= esc($to ?? '') ?>"></div><div class="col-auto align-self-end"><button class="btn btn-primary">Filter</button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><?php foreach ($columns as $label): ?><th><?= esc($label) ?></th><?php endforeach ?></tr></thead><tbody>
